INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "杨璪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国宜阳王。937年受杨溥派遣，前往西都册命齐王徐知诰。", "biography": null, "status": "draft", "id": "b05bfff9-b7c4-5a00-b050-2182684788df"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "齐王妃（徐知诰妻）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐知诰担任齐王时的王妃。937年在吴国册命齐王的记载中被册为王后；此段没有记载她的姓名。", "biography": null, "status": "draft", "id": "331ce8de-2b94-5acb-8d2b-ff60acb0fd25"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "钱传珦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：钱传珦。", "biography": null, "status": "draft", "id": "d1de9767-187e-5fc6-a47b-4a447590a025"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "沙彦珣", "aliases": ["沙彥珣", "沙彦昫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：沙彦珣，奏称中被逐者。", "biography": null, "status": "draft", "id": "14933655-00d4-5df8-b377-9b7c7aac47df"}, {"name": "吴峦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大同军节度判官。沙彦珣被契丹扣留后，他被推举主持云州事务，并闭城拒守。", "biography": null, "status": "draft", "id": "10e5964b-74c7-5654-afc1-4dfbc96d27c3"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "翟璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "威塞节度使。契丹要求他在新州筹集十万缗犒军钱。", "biography": null, "status": "draft", "id": "96b2e88f-4bbd-5920-8f6b-082ca154a484"}, {"name": "阿保机", "aliases": ["阿保機", "耶律阿保机", "耶律阿保機", "邪律阿保机", "邪律阿保機"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷266开平元年条所见人物：阿保机。", "biography": null, "status": "draft", "id": "c632d829-b418-5526-94fd-cc14fddaa9bd"}, {"name": "去诸（西奚王）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "奚王。因不满契丹的统治，率部西迁妫州，依附刘仁恭父子，其部被称为西奚。", "biography": null, "status": "draft", "id": "488543b1-1bf4-59a9-b72e-9c0198c25328"}, {"name": "刘仁恭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“李思安进攻幽州，被刘守光击退”中为卢龙节度使。", "biography": null, "status": "draft", "id": "b8f07571-c891-57ce-b69c-3e4a58148227"}, {"name": "李绍威（西奚王）", "aliases": ["扫刺", "扫剌", "李绍威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "西奚王去诸的儿子，原名扫刺。李存勖灭刘守光后，赐他姓李、名绍威。", "biography": null, "status": "draft", "id": "a24ea105-50d8-5386-ba93-fcc487794a4b"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "逐不鲁之姊（李绍威妻）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "逐不鲁的姐姐，嫁给西奚王李绍威。史书在此段没有记载她的姓名。", "biography": null, "status": "draft", "id": "53b2d1d9-f101-5712-935f-c8549f68091a"}, {"name": "逐不鲁（契丹）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹人。获罪后投奔西奚王李绍威，得到收留。其姐姐嫁给李绍威。", "biography": null, "status": "draft", "id": "36b7607b-ab17-5bd3-8ade-8adf0edec91d"}, {"name": "拽剌（西奚王）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "西奚王李绍威的儿子，在父亲去世后继位。耶律德光从上党北归时，他前往迎接并归降。", "biography": null, "status": "draft", "id": "4098a81e-f684-5a3e-a8d7-3bf67a400198"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "高彦英（契丹通事）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。张砺逃走后，耶律德光责备高彦英没有妥善照顾张砺，并处罚了他。", "biography": null, "status": "draft", "id": "f938393c-f780-5963-a1be-430927856362"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "钱元㺷（吴越王少子）", "aliases": ["钱元珪", "元珪", "元㺷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱镠的少子。《资治通鉴》记载他拥有军功，后掌管吴越土客马步军。937年三月被钱元瓘召入宫中后杀死。姓名在本段中也写作元珪，版本与同名辨认仍待校核。", "biography": null, "status": "draft", "id": "cf91cc3b-4319-56c5-b289-674c0479773a"}, {"name": "钱仁俊", "aliases": ["錢仁俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：钱仁俊，从子、受遣告谕者。", "biography": null, "status": "draft", "id": "8ba65976-a158-523f-a631-fac69d75de34"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

